CREATE FUNCTION cmd_reject_transport_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Transport operation receipts are immutable'; END $$;
CREATE TRIGGER cmd_transport_operation_receipt_immutable BEFORE UPDATE OR DELETE ON cmd_transport_operation_receipt FOR EACH ROW EXECUTE FUNCTION cmd_reject_transport_mutation();
CREATE FUNCTION cmd_validate_transport_receipt() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE task cmd_actor_task_receipt%ROWTYPE; cap rule_transport_skill_capability%ROWTYPE; BEGIN SELECT * INTO STRICT cap FROM rule_transport_skill_capability WHERE rule_id=NEW.mechanic_rule_id AND skill_rule_id=NEW.skill_rule_id; IF cap.target_kind<>NEW.target_kind OR (NEW.target_kind='ship' AND NEW.operation_kind<>'operate-spacecraft') OR (NEW.target_kind='vehicle' AND NEW.operation_kind='operate-spacecraft') OR (NEW.operation_kind='routine-maintenance' AND NOT cap.routine_maintenance_allowed) OR (NEW.operation_kind='maneuver' AND NOT cap.maneuver_allowed) OR (NEW.automatic_success<>(NEW.target_kind='ship' AND NOT NEW.challenging_conditions)) THEN RAISE EXCEPTION 'Transport operation violates its source capability'; END IF; IF NEW.task_command_id IS NOT NULL THEN SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id; IF task.actor_id<>NEW.actor_id OR task.skill_rule_id<>NEW.skill_rule_id OR task.check_total<>NEW.check_total OR task.effect<>NEW.effect OR task.succeeded<>NEW.succeeded THEN RAISE EXCEPTION 'Transport receipt does not match its task'; END IF; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER cmd_transport_operation_receipt_valid AFTER INSERT ON cmd_transport_operation_receipt DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION cmd_validate_transport_receipt();
